import {rem, Skeleton, Text, TextSkeleton} from '@sanity/ui'
import {clsx} from 'clsx'
import {styled} from 'styled-components'
import {Flex, Box} from 'ui5'
import {getDevicePixelRatio} from 'use-device-pixel-ratio'

import {useTranslation} from '../../../i18n/hooks/useTranslation'
import {LinearProgress} from '../../progress/LinearProgress'
import {Media} from '../_common/Media'
import {PREVIEW_SIZES} from '../constants'
import {renderPreviewNode} from '../helpers'
import {type PreviewMediaDimensions, type PreviewProps} from '../types'

/**
 * @hidden
 * @beta */
export interface DefaultPreviewProps extends Omit<PreviewProps<'default'>, 'renderDefault'> {
  styles?: {
    root?: string
    placeholder?: string
    media?: string
    heading?: string
    title?: string
    subtitle?: string
    hasSubtitle?: string
    mediaString?: string
    status?: string
    children?: string
  }
}

const DEFAULT_MEDIA_DIMENSIONS: PreviewMediaDimensions = {
  ...PREVIEW_SIZES.default.media,
  aspect: 1,
  fit: 'crop',
  dpr: getDevicePixelRatio(),
}

const Root = styled(Flex)`
  height: ${rem(PREVIEW_SIZES.default.media.height)};
  box-sizing: content-box;
`

const TitleSkeleton = styled(TextSkeleton).attrs({animated: true, radius: 1, size: 1})`
  max-width: ${rem(160)};
  width: 80%;
`

const SubtitleSkeleton = styled(TextSkeleton).attrs({animated: true, radius: 1, size: 1})`
  max-width: ${rem(120)};
  width: 60%;
`
const SKELETON_DELAY = 300
/**
 * @hidden
 * @beta */
export function DefaultPreview(props: DefaultPreviewProps) {
  const {title, subtitle, media, status, isPlaceholder, children, styles, progress} = props
  const {t} = useTranslation()
  const rootClassName = clsx(styles?.root, Boolean(subtitle) && styles?.hasSubtitle)
  const isUploading = typeof progress === 'number' && progress > -1

  const statusNode = status && (
    <Box className={styles?.status} data-testid="default-preview__status">
      {renderPreviewNode(status, 'default')}
    </Box>
  )

  if (isPlaceholder) {
    // `subtitle` is `undefined` while the value is still loading (both rows), `null` when the
    // resolved value has none (a lazy preview component loading in front of it), so the
    // placeholder has the rows the preview will have.
    const showSubtitleSkeleton = subtitle === undefined || Boolean(subtitle)

    return (
      <Root
        alignItems="center"
        className={styles?.placeholder}
        data-testid="default-preview"
        padding={2}
        paddingLeft={media ? 2 : 3}
      >
        <Flex alignItems="center" flexBasis="0%" flexGrow={1} gap={2}>
          {media && (
            <Box flexBasis="auto" flexGrow={0} flexShrink={0}>
              <Skeleton
                animated
                delay={SKELETON_DELAY}
                radius={1}
                style={PREVIEW_SIZES.default.media}
              />
            </Box>
          )}

          <Flex
            data-testid="default-preview__heading"
            flexBasis="0%"
            flexGrow={1}
            gap={2}
            flexDirection="column"
          >
            <TitleSkeleton delay={SKELETON_DELAY} />
            {showSubtitleSkeleton && <SubtitleSkeleton delay={SKELETON_DELAY} />}
          </Flex>

          <Box flexBasis="auto" flexGrow={0} flexShrink={0} padding={1}>
            {statusNode}
          </Box>
        </Flex>
      </Root>
    )
  }

  return (
    <Root
      alignItems="center"
      className={rootClassName}
      data-testid="default-preview"
      padding={2}
      paddingLeft={media ? 2 : 3}
    >
      <Flex alignItems="center" flexBasis="0%" flexGrow={1} gap={2}>
        {media && (
          <Box flexBasis="auto" flexGrow={0} flexShrink={0}>
            <Media
              dimensions={DEFAULT_MEDIA_DIMENSIONS}
              layout="default"
              media={media as any}
              styles={styles}
            />
          </Box>
        )}

        <Flex
          className={styles?.heading}
          data-testid="default-preview__header"
          flexBasis="0%"
          flexGrow={1}
          gap={2}
          flexDirection="column"
        >
          {isUploading && <LinearProgress value={progress} />}
          {!isUploading && (
            <>
              <Text
                className={styles?.title}
                size={1}
                style={{color: 'inherit'}}
                textOverflow="ellipsis"
                weight="medium"
              >
                {title && renderPreviewNode(title, 'default')}
                {!title && (
                  <span style={{color: 'var(--card-muted-fg-color)'}}>
                    {t('preview.default.title-fallback')}
                  </span>
                )}
              </Text>

              {subtitle && (
                <Text muted size={1} textOverflow="ellipsis" className={styles?.subtitle}>
                  {renderPreviewNode(subtitle, 'default')}
                </Text>
              )}
            </>
          )}
        </Flex>

        <Box flexBasis="auto" flexGrow={0} flexShrink={0} padding={1}>
          {statusNode}
        </Box>

        {children && <div className={styles?.children}>{children}</div>}
      </Flex>
    </Root>
  )
}
