import {Text} from '@sanity/ui'
import {Flex, Box} from 'ui5'
import {getDevicePixelRatio} from 'use-device-pixel-ratio'

import {useTranslation} from '../../../i18n/hooks/useTranslation'
import {Media} from '../_common/Media'
import {PREVIEW_SIZES} from '../constants'
import {renderPreviewNode} from '../helpers'
import {type PreviewMediaDimensions, type PreviewProps} from '../types'
import {
  DescriptionSkeleton,
  DescriptionText,
  MediaSkeleton,
  RootFlex,
  StatusBox,
  SubtitleSkeleton,
  TitleSkeleton,
} from './DetailPreview.styled'

/**
 * @hidden
 * @beta */
export type DetailPreviewProps = PreviewProps<'detail'>

const DEFAULT_MEDIA_DIMENSIONS: PreviewMediaDimensions = {
  ...PREVIEW_SIZES.detail.media,
  fit: 'crop',
  aspect: 1,
  dpr: getDevicePixelRatio(),
}

/**
 * @hidden
 * @beta */
export function DetailPreview(props: DetailPreviewProps) {
  const {
    title,
    subtitle,
    description,
    mediaDimensions = DEFAULT_MEDIA_DIMENSIONS,
    media,
    status,
    children,
    isPlaceholder,
  } = props
  const {t} = useTranslation()

  const statusNode = status && (
    <StatusBox marginLeft={3} paddingRight={1}>
      {renderPreviewNode(status, 'detail')}
    </StatusBox>
  )

  if (isPlaceholder) {
    // `subtitle` is `undefined` while the value is still loading (both rows), `null` when the
    // resolved value has none (a lazy preview component loading in front of it), so the
    // placeholder has the rows the preview will have.
    const showSubtitleSkeleton = subtitle === undefined || Boolean(subtitle)

    return (
      <RootFlex
        data-testid="detail-preview"
        paddingLeft={media ? 2 : 3}
        paddingRight={2}
        paddingY={2}
      >
        <Flex alignItems="center" flexBasis="0%" flexGrow={1} gap={3}>
          {media && <MediaSkeleton data-testid="detail-preview__media" />}

          <Flex
            alignItems="center"
            data-testid="detail-preview__header"
            flexBasis="0%"
            flexGrow={1}
          >
            <Flex flexBasis="0%" flexGrow={1} gap={2} flexDirection="column">
              <TitleSkeleton />
              {showSubtitleSkeleton && <SubtitleSkeleton />}
              {description && (
                <Box marginTop={1}>
                  <DescriptionSkeleton />
                </Box>
              )}
            </Flex>
          </Flex>

          {statusNode}
        </Flex>
      </RootFlex>
    )
  }

  return (
    <RootFlex
      data-testid="detail-preview"
      paddingLeft={media ? 2 : 3}
      paddingRight={2}
      paddingY={2}
    >
      <Flex alignItems="center" flexBasis="0%" flexGrow={1} gap={3}>
        {media && <Media dimensions={mediaDimensions} layout="detail" media={media as any} />}

        <Flex alignItems="center" data-testid="detail-preview__header" flexBasis="0%" flexGrow={1}>
          <Flex flexBasis="0%" flexGrow={1} gap={2} flexDirection="column">
            <Text textOverflow="ellipsis" size={1} style={{color: 'inherit'}} weight="medium">
              {title && renderPreviewNode(title, 'detail')}
              {!title && <>{t('preview.default.title-fallback')}</>}
            </Text>

            {subtitle && (
              <Text muted size={1} textOverflow="ellipsis">
                {renderPreviewNode(subtitle, 'detail')}
              </Text>
            )}

            {description && (
              <Box marginTop={1}>
                <DescriptionText muted size={1}>
                  {renderPreviewNode(description, 'detail')}
                </DescriptionText>
              </Box>
            )}
          </Flex>

          {statusNode}
        </Flex>

        {children}
      </Flex>
    </RootFlex>
  )
}
