import {type ComponentType, type CSSProperties, Suspense, useMemo, useState} from 'react'

import {type PreviewProps} from '../../components/previews/types'
import {type RenderPreviewCallbackProps} from '../../form/types/renderCallback'
import {useTranslation} from '../../i18n/hooks/useTranslation'
import {type PerspectiveStack} from '../../perspective/types'
import {useValuePreview} from '../useValuePreview'
import {useVisibility} from '../useVisibility'
import {_HIDE_DELAY} from './_constants'
import {_extractUploadState} from './_extractUploadState'
import {SanityDefaultPreview} from './SanityDefaultPreview'

/**
 * This component is responsible for converting renderPreview() calls into an element.
 * It:
 * - subscribes to "prepared" preview value as long as the element is visible on screen
 * - resolves the configured preview component for the schema type
 * - prepares "preview"-props and passes this to the configured preview component
 * @internal
 * */
export function PreviewLoader(
  props: RenderPreviewCallbackProps & {
    component: ComponentType<Omit<PreviewProps, 'renderDefault'>>
    perspectiveStack?: PerspectiveStack
    variant?: string
  },
): React.JSX.Element {
  const {
    layout,
    value,
    component: Component,
    style: styleProp,
    schemaType,
    skipVisibilityCheck,
    perspectiveStack,
    variant,
    ...restProps
  } = props

  const {t} = useTranslation()
  const [element, setElement] = useState<HTMLDivElement | null>(null)

  // Subscribe to visibility
  const isVisible =
    useVisibility({
      disabled: skipVisibilityCheck,
      element: element,
      hideDelay: _HIDE_DELAY,
    }) || skipVisibilityCheck

  // Subscribe document preview value
  const preview = useValuePreview({
    enabled: skipVisibilityCheck || isVisible,
    schemaType,
    value,
    perspectiveStack,
    variant,
  })

  const style: CSSProperties = useMemo(
    () => ({
      ...styleProp,
      minWidth: styleProp?.minWidth || 1,
      minHeight: styleProp?.minHeight || 1,
    }),
    [styleProp],
  )

  const uploadState = useMemo(() => _extractUploadState(value), [value])

  const media: PreviewProps['media'] = useMemo(() => {
    if (uploadState?.previewImage) {
      return (
        <img
          alt={t('preview.image.file-is-being-uploaded.alt-text')}
          src={uploadState.previewImage}
        />
      )
    }

    // media: null or false explicitly suppresses the icon.
    // All other falsy cases (undefined, missing key) fall back to the schema icon.
    if (preview?.value?.media === null || preview?.value?.media === false) {
      return undefined
    }

    if (!preview?.value?.media) {
      return schemaType.icon
    }

    // @todo: fix `TS2769: No overload matches this call.`
    return preview?.value?.media as any
  }, [preview, schemaType, uploadState, t])

  // While a lazy preview component loads: the default preview in its placeholder state, with the
  // resolved value, so the fallback has the rows and media slot of the preview that replaces it.
  // A resolved value without a subtitle passes `null`, which the placeholder reads as "no second
  // row"; `undefined` means the value itself is still loading.
  const placeholderSubtitle = preview?.value ? (preview.value.subtitle ?? null) : undefined

  return (
    <div ref={setElement} style={style}>
      <Suspense
        fallback={
          <SanityDefaultPreview
            {...restProps}
            {...(preview?.value || {})}
            isPlaceholder
            layout={layout}
            media={media}
            schemaType={schemaType}
            subtitle={placeholderSubtitle}
          />
        }
      >
        <Component
          {...restProps}
          {...(preview?.value || {})}
          media={media}
          error={preview?.error}
          isPlaceholder={preview?.isLoading}
          layout={layout}
          schemaType={schemaType}
        />
      </Suspense>
    </div>
  )
}
